bridgeLocations = {}
bridgeZones = {}
local currentBridge = {}
local currentBridgeHealth = {}

-- colshapes for bridges
for i, b in ipairs(bridgesPos) do
	bridge[i] = createColPolygon(b[1], b[2], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8])
	setColPolygonHeight(bridge[i], b[10], b[9])

	-- Find center of the bridge
	local minX, maxX = 5000, -5000
	local minY, maxY = 5000, -5000

	-- Min X
	for i = 1, 7, 2 do
		if b[i] < minX then
			minX = b[i]
		end
		if b[i] > maxX then
			maxX = b[i]
		end
	end

	-- Min Y
	for i = 2, 8, 2 do
		if b[i] < minY then
			minY = b[i]
		end
		if b[i] > maxY then
			maxY = b[i]
		end
	end

	-- Calculates center of the bridge (used in blips)
	table.insert(bridgeLocations, {minX + (maxX - minX) / 2, minY + (maxY - minY) / 2})

	-- Get bridge zone
	local bridgeZone = getZoneName(minX + (maxX - minX) / 2, minY + (maxY - minY) / 2, 5, true)
	if bridgeZone == "Los Santos" then
		bridgeZone = "Los Santos - " .. getZoneName(minX + (maxX - minX) / 2, minY + (maxY - minY) / 2, 5, false)
	end

	if bridgeZones[bridgeZone] == nil then
		bridgeZones[bridgeZone] = {}
	end

	-- Insert this bridge into this table of bridge zones
	table.insert(bridgeZones[bridgeZone], i)
end

addEvent("achs_requestBridges", true)
addEventHandler("achs_requestBridges", root, function(togglebridges)
	local data = getAchievementData(source, "flyUnderEveryBridge")
	if data then
		data = fromJSON(data)

		local collectedBridges = {}
		for _, bridgeID in ipairs(data) do -- scan player's progress
			for i, location in ipairs(bridgeLocations) do
				if i == bridgeID then
					table.insert(collectedBridges, {ID = bridgeID, [1] = location[1], [2] = location[2]})
					break
				end
			end
		end
		triggerClientEvent(source, "achs_storeBridges", source, collectedBridges, bridgeZones, togglebridges)
	end
end )

addEventHandler("onColShapeHit", root, function(element)
	if getElementType(element) == "vehicle" and ((getVehicleType(element) == "Plane" and getElementModel(element) ~= 539) or getVehicleType(element) == "Helicopter") and Vector3(getElementVelocity(element)).length > 0.35 and getVehicleOccupant(element) then
		-- Player inside the plane and moving with speed > 0.5
		for i, b in ipairs(bridge) do
			if b == source then
				--if currentBridge[getVehicleOccupant(element)] == nil then
				-- Store the bridge player hit
				currentBridge[getVehicleOccupant(element)] = source
				currentBridgeHealth[getVehicleOccupant(element)] = getElementHealth(element)
				break
			end
		end
	end
end )

addEventHandler("onColShapeLeave", root, function(element)
	if getElementType(element) == "vehicle" and ((getVehicleType(element) == "Plane" and getElementModel(element) ~= 539) or getVehicleType(element) == "Helicopter") and Vector3(getElementVelocity(element)).length > 0.35 and getVehicleOccupant(element) then
		if currentBridge[getVehicleOccupant(element)] and source == currentBridge[getVehicleOccupant(element)] then
			for i, b in ipairs(bridge) do
				if b == source then
					setTimer(function(element, playerSource)
						-- Check if plane is not destroyed
						if isElement(element) and getVehicleOccupant(element) then
							-- Clear the stored bridge
							currentBridge[getVehicleOccupant(element)] = nil

							-- Check if vehicle is not damaged during flying under bridge
							if math.abs(currentBridgeHealth[getVehicleOccupant(element)] - getElementHealth(element)) < 25 and not getElementData(getVehicleOccupant(element), "ach_wheelState") and not isElementInWater(element) then
								updateObjective(getVehicleOccupant(element), "flyUnderBridgeEveryAirVehicle", getElementModel(element))

								-- Update player progress
								local progress, isUpdated = updateObjective(getVehicleOccupant(element), "flyUnderEveryBridge", i)
								if isUpdated then
									-- Figure out zone of this bridge
									local bridgeZone = getZoneName(bridgeLocations[i][1], bridgeLocations[i][2], 5, true)
									if bridgeZone == "Los Santos" then
										bridgeZone = "Los Santos - " .. getZoneName(bridgeLocations[i][1], bridgeLocations[i][2], 5, false)
									end

									local alreadyCollected = 0 -- How many bridges player flown under in this zone already
									if progress then
										for _, v in ipairs(progress) do
											-- Scan through all bridges in table of bridges in this zone
											for _, bridgeInZone in ipairs(bridgeZones[bridgeZone]) do
												if bridgeInZone == v then
													alreadyCollected = alreadyCollected + 1
													break
												end
											end
										end

										-- Send to client new info about their collected bridges
										local dataSend = {}
										for _, bridgeID in ipairs(progress) do
											for i, b in ipairs(bridgeLocations) do
												if i == bridgeID then
													table.insert(dataSend, b)
													break
												end
											end
										end
										triggerClientEvent(playerSource, "achs_storeBridges", playerSource, dataSend)
									else
										progress = {i}
										alreadyCollected = 1
									end

									-- Display text message on the screen for the player
									triggerClientEvent(getVehicleOccupant(element), "achs_collectedBridge", getVehicleOccupant(element), {zone = bridgeZone, total = #bridgesPos, totalinzone = #bridgeZones[bridgeZone], inzone = alreadyCollected, playertotal = #progress})

									-- Player collected every bridge in this zone
									if #bridgeZones[bridgeZone] == alreadyCollected then
										outputChatBox(getPlayerName(getVehicleOccupant(element)) .. " #E7D9B0flew under every bridge in #FFFFFF'" .. bridgeZone .. "'#E7D9B0!", root, 255, 255, 255, true)
									end

									-- Message every 10 bridges
									if #progress % 10 == 0 then
										outputChatBox(getPlayerName(getVehicleOccupant(element)) .. " #E7D9B0flew under #FFFFFF" .. (#progress).. " #E7D9B0bridges!", root, 255, 255, 255, true)
									end
								end
							end
						end
					end, 400, 1, element, source)
					break
				end
			end
		end
	end
end )

addEventHandler("onVehicleEnter", root, function(player, seat)
	if getElementType(player) == "player" and currentBridge[player] ~= nil then
		-- Reset current bridge
		currentBridge[player] = nil
	end
end )
